with recursive UserActivityCTE as (
    select 
        u.Id as UserId,
        u.DisplayName,
        u.Reputation,
        u.CreationDate,
        u.LastAccessDate,
        u.Location,
        count(p.Id)::int as TotalPosts,
        count(case when p.PostTypeId = 1 then 1 end)::int as Questions,
        count(case when p.PostTypeId = 2 then 1 end)::int as Answers,
        (select max(score) 
         from Posts px 
         where px.OwnerUserId = u.Id) as MaxPostScore
    from Users u 
    left join Posts p on p.OwnerUserId = u.Id
    group by u.Id, u.DisplayName, u.Reputation, u.CreationDate, u.LastAccessDate, u.Location

    union all

    select
        u2.Id,
        u2.DisplayName,
        u2.Reputation,
        u2.CreationDate,
        u2.LastAccessDate,
        u2.Location,
        ua.TotalPosts - samples.UpAnswerPosts duplic_macro.Pod淘icmp型hash<Treea……코]],
